// An EventEmitter with no `error` listener throws, so a socket error on a running server ended the process.
describe('a server error after start', () => {
  const engineLines: string[] = [];

  beforeEach(() => {
    engineLines.length = 0;
    const collect = (_category: string, message: string) => void engineLines.push(message);
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  const started = async () => {
    const {hal} = harness();
    await hal.start(0);
    return hal;
  };

  // A stopped engine and a port something else holds, so the next start is refused by the OS.
  const refusedStart = async () => {
    const hal = await started();
    await hal.stop();
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const release = () => new Promise<void>(resolve => blocker.close(() => resolve()));
    return {hal, taken, release};
  };

  it('is reported rather than ending the process', async () => {
    const hal = await started();

    hal.server.emit('error', new Error('late failure'));
    await hal.stop();

    expect(engineLines).toContain('server error after start');
  });

  it('leaves exactly one listener behind, however many times the server is restarted', async () => {
    const hal = await started();
    await hal.stop();
    await hal.start(0);

    const count = hal.server.listenerCount('error');
    await hal.stop();

    expect(count).toBe(1);
  });

  it('is still reported after stop, because an error with no handler ends the process', async () => {
    const hal = await started();
    await hal.stop();

    hal.server.emit('error', new Error('after stop'));

    expect(engineLines).toContain('server error after start');
  });

  it('is not reported for a start that was cleanly refused, because nothing was running', async () => {
    const {hal, taken, release} = await refusedStart();

    await hal.start(taken).catch((error: NodeJS.ErrnoException) => engineLines.push(`rejected ${error.code}`));
    await release();

    expect(engineLines).toEqual(['HAL Engine started', 'rejected EADDRINUSE']);
  });

  it('stops cleanly after a refused start, so a finally block does not turn one failure into two', async () => {
    const {hal, taken, release} = await refusedStart();
    await hal.start(taken).catch(() => undefined);

    const stopped = hal.stop().then(
      () => 'resolved',
      (error: NodeJS.ErrnoException) => `rejected ${error.code}`
    );
    await release();

    await expect(stopped).resolves.toBe('resolved');
  });

  it('refuses a second start without stripping the running server of its handler', async () => {
    const hal = await started();

    await hal.start(0).catch((error: Error) => engineLines.push(`rejected ${error.message}`));
    hal.server.emit('error', new Error('after the refused start'));
    await hal.stop();

    expect(engineLines).toEqual([
      'HAL Engine started',
      'rejected HAL Engine is already started',
      'server error after start',
    ]);
  });
});
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';

export interface MockConfig {
  type: 'mock';
  structuredResponses?: Map<string, unknown>;
}

export function createMockProvider(config?: MockConfig): AIProvider {
  const structuredResponses = config?.structuredResponses ?? new Map<string, unknown>();

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : 'Hello';

      const response = `Mock response to: "${userText}"`;
      const words: MessageChunk[] = response.split(' ').map(word => ({type: 'text', text: word + ' '}));
      const stop: MessageChunk = {
        type: 'stop',
        stopReason: 'end_turn',
        usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30},
      };

      // Checked before every chunk, so an abort ends the stream at once and no stop chunk follows it.
      for (const chunk of [...words, stop]) {
        if (params.signal?.aborted) return;
        yield chunk;
      }
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : '';

      const preconfigured = structuredResponses.get(userText);
      if (preconfigured !== undefined) return preconfigured as T;

      return buildDefaultResponse(params.responseSchema) as T;
    },
  };
}

// Factories, not values: `array` must hand back a fresh [] to each caller.
const SCALAR_DEFAULTS: Record<string, () => unknown> = {
  array: () => [],
  string: () => '',
  number: () => 0,
  boolean: () => false,
};

function buildDefaultResponse(schema: {type: string; properties?: Record<string, {type: string}>}): unknown {
  if (schema.type === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, prop] of Object.entries(schema.properties ?? {})) {
      result[key] = buildDefaultResponse(prop);
    }
    return result;
  }

  const scalar = SCALAR_DEFAULTS[schema.type];
  return scalar ? scalar() : null;
}
import type {ChatSession} from '../../types/session.js';
import type {
  SessionStore,
  SessionCreateOptions,
  SessionListOptions,
  SessionLookup,
  SessionSummary,
} from '../../types/sessionStore.js';
import {cappedLimit, cursorAt, newestFirst, sitsAfter} from './sessionListWindow.js';

// Eight hours: a memory bound, not a retention decision (specs/hal-engine-session-lifetime/spec.md).
const DEFAULT_MAX_AGE_MS = 8 * 60 * 60 * 1000;

export interface InMemorySessionStoreOptions {
  maxAgeMs?: number;
}

// The creation time is held beside the session rather than on it, so it never reaches the public ChatSession.
interface HeldSession {
  session: ChatSession;
  createdAt: number;
}

export class InMemorySessionStore implements SessionStore {
  private readonly sessions = new Map<string, HeldSession>();
  private readonly maxAgeMs: number;

  constructor(options: InMemorySessionStoreOptions = {}) {
    this.maxAgeMs = options.maxAgeMs ?? DEFAULT_MAX_AGE_MS;
  }

  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): ChatSession {
    this.sweepExpired();

    const session: ChatSession = {
      sessionId,
      userId,
      entries: [],
      authHeaders: options?.authHeaders,
      workspaceId: options?.workspaceId,
    };
    this.sessions.set(sessionId, {session, createdAt: Date.now()});
    return session;
  }

  get(sessionId: string): ChatSession | undefined {
    const held = this.sessions.get(sessionId);
    if (held === undefined) return undefined;
    if (!this.hasExpired(held)) return held.session;

    this.sessions.delete(sessionId);
    return undefined;
  }

  /** One shot: a session past `maxAgeMs` answers `expired` once and is evicted, never kept as a tombstone. */
  lookup(sessionId: string): SessionLookup {
    const held = this.sessions.get(sessionId);
    if (held === undefined) return {status: 'missing'};
    if (!this.hasExpired(held)) return {status: 'active', session: held.session};

    this.sessions.delete(sessionId);
    return {status: 'expired', userId: held.session.userId};
  }

  delete(sessionId: string): boolean {
    return this.sessions.delete(sessionId);
  }

  // Eviction and erasure coincide for a store that is only a cache; they do not for a durable one.
  evict(sessionId: string): boolean {
    return this.sessions.delete(sessionId);
  }

  count(): number {
    return this.sessions.size;
  }

  clear(): void {
    this.sessions.clear();
  }

  /** Summaries of the user's live sessions, newest activity first, by the same activity `latestFor` reads. */
  listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
    const limit = cappedLimit(options?.limit);
    if (limit === 0) return [];

    const ordered = this.ownedBy(userId).map(summaryOf).sort(newestFirst);
    const before = options?.before;
    if (before === undefined) return ordered.slice(0, limit);

    const at = cursorAt(before);
    return ordered.filter(summary => sitsAfter(summary, at, before.sessionId)).slice(0, limit);
  }

  /** The user's most recently active session that has not aged out: its newest entry decides, or its creation if it has none. */
  latestFor(userId: string | number): ChatSession | undefined {
    // Ascending and stable, so of two sessions last active at the same moment, the one created later wins.
    return this.ownedBy(userId).sort(byActivity).at(-1)?.session;
  }

  // Their own array, so a caller's sort never reorders the map's insertion order, which the sweep depends on.
  private ownedBy(userId: string | number): HeldSession[] {
    return [...this.sessions.values()].filter(held => held.session.userId === userId && !this.hasExpired(held));
  }

  // Insertion order approximates age order, so the first live entry ends the sweep and the rest cost nothing.
  private sweepExpired(): void {
    for (const [sessionId, held] of this.sessions) {
      if (!this.hasExpired(held)) return;
      this.sessions.delete(sessionId);
    }
  }

  // A session stamped with an unusable clock reading never ages out, rather than expiring immediately.
  private hasExpired(held: HeldSession): boolean {
    return Number.isFinite(held.createdAt) && Date.now() - held.createdAt > this.maxAgeMs;
  }
}

// Ascending and stable, so latestFor's `.at(-1)` takes the session created later when two are last active together.
function byActivity(first: HeldSession, second: HeldSession): number {
  return lastActivity(first) - lastActivity(second);
}

function summaryOf(held: HeldSession): SessionSummary {
  const {session} = held;
  return {
    sessionId: session.sessionId,
    createdAt: new Date(held.createdAt),
    updatedAt: new Date(lastActivity(held)),
    entryCount: session.entries.length,
  };
}

// The store has no save to stamp, so activity is read off the entries; an unusable clock reading counts as none.
function lastActivity(held: HeldSession): number {
  const {entries} = held.session;
  const stamps = entries.map(entry => ('timestamp' in entry ? Date.parse(entry.timestamp) : Number.NaN));
  // Folded rather than spread into Math.max, whose argument list runs out past about 150,000 entries.
  return [held.createdAt, ...stamps].filter(Number.isFinite).reduce((latest, time) => Math.max(latest, time), 0);
}
import type {ChatSession} from './session.js';

/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
export type Awaitable<T> = T | Promise<T>;

export interface BaseSession {
  sessionId: string;
  userId: string | number;
}

/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
export type SessionLookup<T extends BaseSession = ChatSession> =
  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};

/** What a conversation list needs of one session: never its entries, and never its credentials. */
export interface SessionSummary {
  sessionId: string;
  createdAt: Date;
  updatedAt: Date;
  entryCount: number;
}

/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
export interface SessionCursor {
  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
  updatedAt: Date | string | number;
  sessionId: string;
}

/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
export interface SessionListOptions {
  limit?: number;
  before?: SessionCursor;
}

export interface SessionCreateOptions {
  authHeaders?: ChatSession['authHeaders'];
  workspaceId?: string | number;
}

export interface SessionStore<T extends BaseSession = ChatSession> {
  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
  get(sessionId: string): Awaitable<T | undefined>;
  delete(sessionId: string): Awaitable<boolean>;
  count(): Awaitable<number>;
  clear(): Awaitable<void>;
  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
  evict?(sessionId: string): Awaitable<boolean>;
  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
  save?(session: T): Awaitable<void>;
  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
  latestFor?(userId: string | number): Awaitable<T | undefined>;
  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
}
# AGENTS.md

## Context Loading Order

Agents should read files in this order to understand the HAL Engine codebase:

1. **README.md** - Overview, features, quick start, and project structure
2. **package.json** - Dependencies, scripts, tech stack validation
3. **tsconfig.json** - TypeScript configuration and compilation targets
4. **src/index.ts** - Public API exports and module surface
5. **src/config.ts** - Main factory function `createHalEngine()` and configuration schema
6. **src/types/** - Core type definitions (ai.ts, session.ts, messages.ts, auth.ts, sessionStore.ts)
7. **src/providers/** - AI provider implementations (bedrock, vertex, openai, anthropic, mock)
8. **src/infrastructure/** - Support layers (builders, stores, parsers)
9. **src/orchestration/** - Business logic (chatOrchestrator, tools, context management)
10. **src/transport/** - Server setup (Express app, WebSocket, routes)
11. **specs/** - Normative specs (architecture, WebSocket protocol, providers, tool responses)
12. **adrs/** - Architecture Decision Records
13. **docs/** - How-to guides, coding practices, and research spikes under docs/spikes/
14. **.specify/spec.md** - Repo-level system spec (exempt from the spec header table convention)

## Workflow Commands

### Development
```bash
npm run dev          # Start example/server.ts with hot reload (tsx watch)
npm run typecheck    # Run TypeScript type checking without emitting
```

### Building
```bash
npm run build        # Compile TypeScript to dist/ (tsc)
npm start            # Run compiled JavaScript from dist/index.js
```

### Testing
```bash
npm test             # Run Jest test suite
# Tests use ts-jest for TypeScript compilation
# Configuration: jest.config.js
```

### Code Quality
```bash
npm run eslint       # Run ESLint with max-warnings 0 (zero-tolerance)
npm run prettier     # Format all src/**/*.ts with Prettier
npm run prettier:check  # Check formatting without writing
```

### All Checks (Recommended Pre-Commit)
```bash
npm run verify
```

That is the blocking set `.github/workflows/ci.yml`'s `verify` job runs on every
pull request, in the same order, and `scripts/verify-script.test.ts` fails if the
two stop agreeing - so this command cannot quietly become a subset of what CI
demands. Two gates in that job are missing from it because both diff against
`origin/main` and neither runs the same way on a checkout: the spec anchor check
and the changelog check.

Two further CI jobs are worth running locally before a release or a change that
touches packaging: `npm run check:build-chain` (audit and action pins) and
`npm run smoke` (packs the tarball and installs it outside this tree).

## Spec Header Table

Every `specs/*/spec.md` opens with its title, then a two-column header table,
and carries a lead paragraph of prose before its first `##` section:

```markdown
# <spec title>

| Field  | Value                  |
| ------ | ---------------------- |
| Issue  | re-cinq/HALEngine#<n> |
| Status | Draft                  |

<lead paragraph>
```

The lead paragraph does not have to sit immediately after the table: a spec
carrying a metadata block of its own may place that block between the two. What
the convention requires is that prose, rather than a section heading, follows
the header material, and that the prose runs to at least 40 characters -
anything shorter is reported as no lead paragraph at all.

`Issue` names the issue the spec was written against, or `n/a` for the specs
that predate this convention.

`Status` is one of `Draft`, `In Progress` or `Shipped`. It is not a mood, and
it is not a claim about how finished the feature is: it is the spec's own
test-citation coverage. No testable statement cited is `Draft`, some cited is
`In Progress`, all cited is `Shipped`. A spec describing shipped, working
behaviour still reads `Draft` until its statements cite the tests that
validate them.

A spec that should no longer be graded takes a terminal value instead. The
parser buckets roughly sixteen labels into five buckets, and the two terminal
ones skip the coverage check whatever the citation count:

| Written into the spec                                            | Bucket                       |
| ---------------------------------------------------------------- | ---------------------------- |
| `Draft`                                                          | `draft`                      |
| `In Progress`, `In Review`, `Planning`, `WIP`, `Proposed`        | `in-progress`                |
| `Shipped`, `Implemented`, `Complete`, `Accepted`, `Done`, `Live` | `shipped`                    |
| `Retired`, `Superseded`, `Removed`, `Deprecated`, `Obsolete`     | `retired` - skips the check  |
| `Rejected`, `Abandoned`                                          | `rejected` - skips the check |

Prefer the canonical `Draft` / `In Progress` / `Shipped` for a live spec; reach
for `Retired` or `Rejected` rather than leaving a superseded spec to claim a
coverage tier it will never earn.

ADRs do not carry this table. They declare their state as YAML frontmatter
`status:` instead - `accepted` for a decision the code implements, `proposed`
for one it does not. That field does mean maturity, which the spec `Status` row
explicitly does not. The difference is deliberate: ADRs are exempt from the
coverage tier, because asking a decision record to cite a test for every
statement it makes is the wrong ask of a decision record.

`.specify/spec.md` is exempt from this section. It is the repo-level system
spec, it predates the convention, and its content is deliberately frozen -
giving it a header table and a lead paragraph would mean writing new prose into
a file that is meant to stay unchanged. The exemption covers the header table
and the lead paragraph only: the Lore coverage job does scan
`.specify/spec.md`, so link placement still applies to it.

## Spec Test Links

Statements in `specs/*/spec.md` cite their validating test in a trailing
parenthetical at the end of the statement, where a list item counts as one
statement and a paragraph counts per sentence. Tests live beside their source
in this repo, so the path points into `src/`:

```markdown
- All entries within a single assistant response are committed before the next
  user message is processed
  ([validated by: commits every entry before the next user message](../../src/orchestration/chatOrchestrator.test.ts#L42)).
```

The citation carries the test's **name** as well as its line. The name is what the
author cited; the line is a derived pointer, and it goes stale on its own - adding
an import above a suite moves every test below it, and the citation lands on a
different, still-valid declaration without anything noticing. `npm run spec:names`
holds each citation to the test it names, and `npm run spec:names:fix` repoints the
line from the name. The `#Lnn` stays because the lint rule and the coverage job
both index by it; a citation without one marks the whole file covered rather than
one test.

A citation counts as coverage only where it is trailing, and a test link placed
anywhere else in the statement is a misplaced citation rather than a weaker one.
Upstream `check:spec-links` reports it and exits 1, and the coverage job that
consumes these specs records nothing for it - so a spec can read as fully cited while its coverage is
zero. A mid-statement link to something that is not a test file - a script, a
doc, another spec - is ordinary prose, is never reported, and was never coverage
to begin with. A misplaced citation is fixed by moving it to the end of its
statement, never by deleting it.

In a test file the `#Lnn` anchor must land on the `it(`, `test(` or `describe(`
declaration itself - not a blank line, not one holding only closing punctuation,
and not a line inside the test body. A citation onto an `expect` renders and
resolves like any other, and proves nothing: no reader can turn that line back
into the name of a case. `scripts/repoint-spec-anchors.mjs` reports all four as
`rotten` and exits 1 in both modes. A citation into a file that is not a test -
a workflow, a config, `package.json` - has no declaration to land on and is held
only to existing and carrying content.

What no gate can catch is an anchor aimed at the wrong declaration: a real but
unintended `it(` passes every check. The tell is that the test the statement
meant to cite goes on reading as uncited in the `require-spec-link` backlog.

Anchors drift silently whenever a cited file gains or loses lines above them, so
after editing any cited file re-run `node scripts/repoint-spec-anchors.mjs`
rather than hand-correcting the numbers. That script cannot repair a spec absent
from the base ref, since it has no baseline to translate from; on the branch that
introduces a spec, its anchors have to be corrected by hand.

The convention's tooling is wired up here: `npm run check:spec-links`, `npm run check:spec-status` and
`node scripts/repoint-spec-anchors.mjs --check origin/main` all gate CI, and
`re-lint/require-status-matches-coverage` derives each `Status` row from its

